"""Login (scrypt) + JWT. Users live in config/users.yaml (generated by `tl.py init`, gitignored)."""
from __future__ import annotations

import base64
import hashlib
import hmac
import os
import time
from dataclasses import dataclass
from pathlib import Path

import jwt
import yaml
from fastapi import Depends, HTTPException, Request

SECRET = os.environ.get("JWT_SECRET", "dev-only-secret-change-me-0123456789abcdef")
USERS_FILE = Path(os.environ.get("USERS_FILE", "/config/users.yaml"))
TTL_S = 8 * 3600


@dataclass
class User:
    email: str
    tenant: str  # "*" for platform-ops
    role: str  # tenant-admin | tenant-viewer | platform-ops

    @property
    def is_ops(self) -> bool:
        return self.role == "platform-ops"


def _b64d(s: str) -> bytes:
    return base64.urlsafe_b64decode(s + "=" * (-len(s) % 4))


def verify_scrypt(stored: str, password: str) -> bool:
    try:
        _, n, r, p, salt, h = stored.split("$")
        got = hashlib.scrypt(password.encode(), salt=_b64d(salt), n=int(n), r=int(r), p=int(p), dklen=32)
        return hmac.compare_digest(got, _b64d(h))
    except Exception:
        return False


def users() -> list[dict]:
    if not USERS_FILE.exists():
        return []
    return (yaml.safe_load(USERS_FILE.read_text(encoding="utf-8")) or {}).get("users", [])


def login(email: str, password: str) -> tuple[str, User]:
    for u in users():
        if u["email"].lower() == email.lower().strip() and verify_scrypt(u.get("scrypt", ""), password):
            user = User(u["email"], u["tenant"], u["role"])
            tok = jwt.encode({"sub": user.email, "tenant": user.tenant, "role": user.role,
                              "exp": int(time.time()) + TTL_S}, SECRET, algorithm="HS256")
            return tok, user
    time.sleep(0.3)  # flat-ish failure timing
    raise HTTPException(401, "invalid email or password")


def decode(token: str) -> User:
    try:
        d = jwt.decode(token, SECRET, algorithms=["HS256"])
    except jwt.PyJWTError as e:
        raise HTTPException(401, f"invalid token: {e}") from e
    return User(d["sub"], d["tenant"], d["role"])


def current_user(req: Request) -> User:
    h = req.headers.get("authorization", "")
    tok = h[7:] if h.lower().startswith("bearer ") else req.cookies.get("tl_token", "")
    if not tok:
        raise HTTPException(401, "login required")
    return decode(tok)


def tenant_user(user: User = Depends(current_user)) -> User:
    if user.is_ops:
        raise HTTPException(403, "platform-ops sees fleet health only, not tenant telemetry")
    return user


def admin_user(user: User = Depends(tenant_user)) -> User:
    if user.role != "tenant-admin":
        raise HTTPException(403, "tenant-admin role required")
    return user
